//! The vendor's Linux programs and their policies, generated by build.rs
//! from userland/capsule_linux/policies.txt. The only copy: capsule_linux
//! binds by it, and the market and nonos_proof_abi check vendor policies
//! against it. Empty when the build names no Linux userland.

use super::row::VendorRow;

pub static TABLE: &[VendorRow] = include!(concat!(env!("OUT_DIR"), "/vendor_table.rs"));

/// The row for the program whose file hashes to `program`, if the vendor
/// ships it.
pub fn by_program(program: &[u8; 32]) -> Option<&'static VendorRow> {
    TABLE.iter().find(|r| r.program_blake3 == *program)
}
